import re, math

def _extract_boxed(text):
    idx = text.rfind("\\boxed{")
    if idx == -1:
        return None
    depth = 0
    start = idx + len("\\boxed{")
    for i in range(start, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            if depth == 0:
                return text[start:i]
            depth -= 1
    return None

def _clean_latex_number(s):
    s = re.sub(r"\\text\{[^}]*\}", "", s)
    s = re.sub(r"\\(mathrm|mathbf|textbf)\{([^}]*)\}", r"\2", s)
    s = s.replace("\\!", "").replace("\\,", "").replace("\\;", "")
    s = s.replace("$", "").replace("%", "").replace("\\$", "")
    s = s.replace(",", "").replace(" ", "")
    return s.strip()

def extract_answer(text):
    clean = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL)
    if not clean.strip():
        clean = text
    boxed = _extract_boxed(clean)
    if boxed is not None:
        return _clean_latex_number(boxed)
    hash_match = re.findall(r"####\s*(.+)", clean)
    if hash_match:
        return hash_match[-1].strip().replace(",", "")
    numbers = re.findall(r"-?\d+(?:,\d{3})*(?:\.\d+)?", clean)
    if numbers:
        return numbers[-1].replace(",", "")
    return None

def normalize_answer(ans):
    if ans is None: return None
    ans = ans.strip().replace(",", "").replace(" ", "")
    if not ans: return None
    try:
        val = float(ans)
        if not math.isfinite(val): return None
        if val == int(val): return str(int(val))
        return str(val)
    except (ValueError, OverflowError):
        return ans

